import { createMemo, JSX, ParentComponent, Show } from "solid-js";

import ContextManager from "#core/ui/context-manager/context-manager.js";
import { ScreenProfilePageExternalStatus } from "#core/ui/profile-page/screen-profile-page.js";
import { Layout } from "#core/ui/utilities/utilities-layout.js";
import { getPlayerCardInfo } from "#core/ui/utilities/utilities-liveops.js";
import { Activatable } from "#core/ui-next/components/activatable.jsx";
import { Button } from "#core/ui-next/components/button.jsx";
import { ConfirmationDialog } from "#core/ui-next/components/confirmation-dialog.jsx";
import { L10n } from "#core/ui-next/components/l10n.jsx";
import { NavHelp } from "#core/ui-next/components/nav-help.jsx";
import { BadgeSize, ProgressionBadge } from "#core/ui-next/components/progression-badge.jsx";
import { Background3d, BackgroundLayer3d, Scene3d } from "#core/ui-next/components/scene-3d.jsx";
import { useScreenFlowContext } from "#core/ui-next/components/screen-flow.jsx";
import { AgeSelectModel } from "#core/ui-next/screens/create-game/age-select-model.js";
import {
	CreateGameBackButtton,
	CreateGameNavButton,
} from "#core/ui-next/screens/create-game/create-game-components.jsx";
import { ComponentRegistry } from "#core/ui-next/services/component-registry.js";
import { LayoutModel, useIsSmallScreen } from "#core/ui-next/utilities/layout-utilities.js";

import style from "./create-game-stage.scss?url";

export enum CreateGameStageMode {
	Full,
	StageOnly,
	HeaderOnly,
	None,
}

export interface CreateGameStageProps {
	header: JSX.Element;
	backgroundImage?: string;
	backgroundOpacity?: number;
	addTextBgGradient?: boolean;
	hideLowerHeaderFiligree?: boolean;
	/** Default: Full */
	mode?: CreateGameStageMode;
}

const CreateGameStageComponent: ParentComponent<CreateGameStageProps> = (props) => {
	const layout = LayoutModel.get();
	const ageModel = AgeSelectModel.get();

	const isSmallScreen = useIsSmallScreen();
	const horizScaleFactor = createMemo(() => layout.screenWidth() / 1920);

	const headerHeight = layout.toScaledPixels(130);
	const headerHeightSmall = layout.toScaledPixels(84);

	const footerHeight = layout.toScaledPixels(isSmallScreen() ? 0 : 60);

	const getHeaderHeight = createMemo(() => {
		return isSmallScreen() ? headerHeightSmall() : headerHeight();
	});

	const getBodyHeight = createMemo(() => {
		return layout.screenHeight() - getHeaderHeight() - footerHeight();
	});

	const shadowBottomOffset = createMemo(() => footerHeight() - getHeaderHeight());

	const gradientBaseSize = layout.toScaledPixels(2048);
	const gradientBaseOffset = layout.toScaledPixels(-76);
	const gradientSize = createMemo(() => gradientBaseSize() * horizScaleFactor());
	const gradientOffset = createMemo(() => gradientBaseOffset() * horizScaleFactor());

	const stageGradientWidthBase = layout.toScaledPixels(1800);
	const stageGradientWidth = createMemo(() => stageGradientWidthBase() * horizScaleFactor());

	const headerBgFiligreeWidth = layout.toScaledPixels(990);
	const headerBgFiligreeHeight = layout.toScaledPixels(250);

	const headerBgFiligreeOffsetX = layout.toScaledPixels(6);
	const headerBgFiligreeOffsetY = layout.toScaledPixels(9);

	const dividerLineExtension = layout.toScaledPixels(64);
	const dividerLineWidth = createMemo(() => dividerLineExtension() + layout.screenWidth());
	const dividerLineHeight = layout.toScaledPixels(16);

	const showStage = createMemo(
		() => props.mode != CreateGameStageMode.HeaderOnly && props.mode != CreateGameStageMode.None,
	);

	const showHeader = createMemo(
		() => props.mode != CreateGameStageMode.StageOnly && props.mode != CreateGameStageMode.None,
	);

	const showBg = createMemo(() => props.mode == CreateGameStageMode.Full || !props.mode);

	// TODO: this should be data driven
	const defaultAgeBg = createMemo(
		() => `${ageModel.selectedAge.type.toLowerCase().replace("age_", "shell_")}-select`,
	);

	return (
		<>
			<Scene3d name="create-game-stage">
				<Background3d>
					<Show when={showBg()}>
						<BackgroundLayer3d
							name="bg-gradeint"
							texture="mm_allgradient"
							size={{ x: gradientSize(), y: gradientSize() }}
							offset={{ x: 0, y: gradientOffset() }}
							alignY={AlignMode.Maximum}
							stretch={StretchMode.UniformFill}
						/>
					</Show>
					<Show when={showHeader()}>
						<BackgroundLayer3d
							name="header-filigree-left"
							texture="base_frame-filigree"
							size={{ x: headerBgFiligreeWidth(), y: headerBgFiligreeHeight() }}
							alignX={AlignMode.Minimum}
							alignY={AlignMode.Minimum}
							offset={{ x: headerBgFiligreeOffsetX(), y: headerBgFiligreeOffsetY() }}
							borderImageSlice="140 1 1 140"
							borderImageWidth="140 1 1 140"
							alpha={0.15}
						/>
						<BackgroundLayer3d
							name="header-filigree-right"
							texture="base_frame-filigree"
							size={{ x: headerBgFiligreeWidth(), y: headerBgFiligreeHeight() }}
							alignX={AlignMode.Maximum}
							alignY={AlignMode.Minimum}
							flipX={true}
							offset={{ x: headerBgFiligreeOffsetX(), y: headerBgFiligreeOffsetY() }}
							borderImageSlice="140 140 1 1"
							borderImageWidth="140 140 1 1"
							alpha={0.15}
						/>
						<Show when={!isSmallScreen()}>
							<BackgroundLayer3d
								name="footer-filigree-left"
								texture="base_frame-filigree"
								size={{ x: headerBgFiligreeWidth(), y: headerBgFiligreeHeight() }}
								alignX={AlignMode.Minimum}
								alignY={AlignMode.Maximum}
								flipY={true}
								offset={{ x: headerBgFiligreeOffsetX(), y: headerBgFiligreeOffsetY() }}
								borderImageSlice="1 1 140 140"
								borderImageWidth="1 1 140 140"
								alpha={0.15}
							/>
							<BackgroundLayer3d
								name="footer-filigree-right"
								texture="base_frame-filigree"
								size={{ x: headerBgFiligreeWidth(), y: headerBgFiligreeHeight() }}
								alignX={AlignMode.Maximum}
								alignY={AlignMode.Maximum}
								flipY={true}
								flipX={true}
								offset={{ x: headerBgFiligreeOffsetX(), y: headerBgFiligreeOffsetY() }}
								borderImageSlice="1 140 140 1"
								borderImageWidth="1 140 140 1"
								alpha={0.15}
							/>
						</Show>
					</Show>
					<Show when={showStage()}>
						<BackgroundLayer3d
							name="stage-bg-gradient"
							texture="mm_allgradient"
							size={{ x: layout.screenWidth(), y: getBodyHeight() }}
							offset={{ x: 0, y: getHeaderHeight() }}
							alignY={AlignMode.Minimum}
							stretch={StretchMode.UniformFill}
						/>

						<BackgroundLayer3d
							name="stage-body"
							texture={props.backgroundImage ?? defaultAgeBg()}
							size={{ x: layout.screenWidth(), y: getBodyHeight() }}
							offset={{ x: 0, y: getHeaderHeight() }}
							alignY={AlignMode.Minimum}
							alpha={props.backgroundOpacity ?? 0.15}
							stretch={StretchMode.UniformFill}
						/>

						<Show when={!props.addTextBgGradient}>
							<BackgroundLayer3d
								name="stage-gradient"
								texture="create_game_gradient1"
								size={{ x: stageGradientWidth(), y: getBodyHeight() }}
								offset={{
									x: 0,
									y: getHeaderHeight(),
								}}
								alignY={AlignMode.Minimum}
								alignX={AlignMode.Minimum}
								alpha={0.85}
								stretch={StretchMode.UniformFill}
							/>
						</Show>
						<BackgroundLayer3d
							name="shadow-top"
							texture="create_game_gradient3"
							size={{
								x: layout.screenWidth(),
								y: getHeaderHeight(),
							}}
							alignY={AlignMode.Minimum}
							alpha={0.5}
						/>
						<Show when={!isSmallScreen()}>
							<BackgroundLayer3d
								name="shadow-bottom"
								texture="create_game_gradient3"
								size={{
									x: layout.screenWidth(),
									y: getHeaderHeight(),
								}}
								offset={{ x: 0, y: shadowBottomOffset() }}
								alignY={AlignMode.Maximum}
								flipY={true}
								alpha={0.5}
							/>
						</Show>
						<BackgroundLayer3d
							name="stage-divider-top"
							texture="hud_section-line_gold"
							size={{ x: dividerLineWidth(), y: dividerLineHeight() }}
							offset={{ x: 0, y: getHeaderHeight() }}
							alignX={AlignMode.Center}
							alignY={AlignMode.Minimum}
							borderImageSlice="1 40 1 40"
							borderImageWidth="1 40 1 40"
						/>
						{/* <Show when={!smallResolution()}> */}
						<BackgroundLayer3d
							name="stage-divider-bottom"
							texture="hud_section-line_gold"
							size={{ x: dividerLineWidth(), y: dividerLineHeight() }}
							offset={{ x: 0, y: footerHeight() }}
							alignX={AlignMode.Center}
							alignY={AlignMode.Maximum}
							flipY={true}
							borderImageSlice="1 40 1 40"
							borderImageWidth="1 40 1 40"
						/>
						{/* </Show> */}
					</Show>
				</Background3d>
			</Scene3d>
			<div class="fullscreen">
				<div class="create-game-stage-header">{props.header}</div>
				<div
					class="create-game-stage-body relative flex-auto"
					style={{ height: `${getBodyHeight()}px`, "max-height": `${getBodyHeight()}px` }}
				>
					{/* gradient */}
					<div
						class={`absolute top-0 my-0\\.5 overflow-hidden ${isSmallScreen() ? `fullscreen-outside-safezone-x-bot` : `fullscreen-outside-safezone-x bottom-0`}`}
					>
						<div
							class="absolute inset-y-px -left-1 pointer-events-none"
							classList={{ "create-game-text-gradient": props.addTextBgGradient }}
							style={{ right: "40%" }}
						/>
					</div>
					{/* between header and body filigrees */}
					<div class="absolute left-0 right-0 -top-5 flex flex-row items-center justify-center -scale-y-100">
						<Show when={!props.hideLowerHeaderFiligree}>
							<div class="filigree-divider-h2" />
						</Show>
					</div>
					{/* actual body */}
					<div class="absolute inset-y-1 inset-x-0">{props.children}</div>
				</div>
			</div>
		</>
	);
};

export const CreateGameStage = ComponentRegistry.register({
	name: "CreateGameStage",
	createInstance: CreateGameStageComponent,
	styles: [style],
});

export enum ExitButtonPosition {
	Left,
	Right,
	None,
}

export interface CreateGameStageHeaderProps {
	showSteps: boolean;
	title: string;
	exitText?: string;
	exitHotkey?: string;
	hideButtonText?: string;
	onBack?: () => void;
}

const CreateGameStageHeaderComponent: ParentComponent<CreateGameStageHeaderProps> = (props) => {
	const context = useScreenFlowContext();

	const isMobile = UI.getViewExperience() == UIViewExperience.Mobile;
	const isSmallScreen = useIsSmallScreen();
	const badgeSize = createMemo(() =>
		isSmallScreen() ? (isMobile ? BadgeSize.SMALL : BadgeSize.MICRO) : BadgeSize.MINI,
	);

	const playerCardInfo = createMemo(() => getPlayerCardInfo());

	function onProgressionBadge() {
		if (Network.isMetagamingAvailable()) {
			ScreenProfilePageExternalStatus.isGameCreationDomainInitialized = true;
			ContextManager.push("screen-profile-page", {
				singleton: true,
				createMouseGuard: true,
				panelOptions: { onlyChallenges: false, onlyLeaderboards: false },
			});
		}
	}

	const exitHotkey = createMemo(() => props.exitHotkey ?? "shell-action-2");

	return (
		<div class="create-game-stage-header-container pb-6 h-full flex flex-col items-center justify-center relative">
			<div class="h-5">
				<Show when={props.showSteps}>
					<div
						class="text-tertiary-1 flex flex-row uppercase"
						style={{ "font-size": Layout.pixels(16) }}
					>
						<L10n.Compose
							text="LOC_UI_CREATE_GAME_STEP_NUM_OF_TOT"
							args={[context.currentStep(), context.numSteps()]}
						/>
					</div>
				</Show>
			</div>
			<div class="grow" />
			<div class="flex flex-row items-center justify-center -my-1\.5">
				<div class="create-games-stage-header-filigree mt-1" />
				<div class="create-game-header-title font-title text-tertiary-1 font-black mx-7 uppercase">
					<L10n.Compose text={props.title} />
				</div>
				<div class="create-games-stage-header-filigree mt-1 -scale-x-100" />
			</div>
			<div class="grow" />
			{props.children}
			<div class="create-game-header-left-button-area flex flex-row items-center justify-center absolute">
				<CreateGameBackButtton onBack={props.onBack} />
				<Show when={!!props.exitText}>
					<ConfirmationDialog
						name="exit-to-menu"
						onAccept={() => context.close()}
						title={<L10n.Compose text="LOC_UI_CREATE_GAME_EXIT_TO_MENU" />}
					>
						<CreateGameNavButton
							class="ml-4"
							hotkeyAction={exitHotkey()}
							navTrayText={props.exitText}
							disableFocus={true}
						>
							<L10n.Stylize
								class="font-fit-shrink"
								text={props.exitText!}
							/>
						</CreateGameNavButton>
					</ConfirmationDialog>
				</Show>
			</div>
			<div class="create-game-header-right-button-area flex flex-row items-center justify-center absolute">
				<Show when={!!props.hideButtonText}>
					<Button
						onActivate={() => context.close()}
						hotkeyAction={exitHotkey()}
						navTrayText={props.hideButtonText}
						disableFocus={true}
					>
						{props.hideButtonText}
					</Button>
				</Show>
			</div>
			<Show when={!UI.isInGame()}>
				<Activatable
					class="absolute right-6 top-6 create-game-badge-container relative group"
					onActivate={onProgressionBadge}
					disableFocus={true}
					hotkeyAction="sys-menu"
				>
					<div
						class="create-game-badge-container img-prof-btn-bg pointer-events-auto relative group group-pressed\:scale-110 group-hover\:scale-110 group-focus\:scale-110"
						data-tooltip-content={playerCardInfo().twoKName}
					>
						<div
							class="absolute inset-0 opacity-30 group-pressed\:scale-110 group-hover\:scale-110 group-focus\:scale-110"
							style={{ "background-color": playerCardInfo().BackgroundColor }}
						/>
						<ProgressionBadge
							badgeSize={badgeSize()}
							badgeUrl={playerCardInfo().BadgeURL}
							progressionLevel={playerCardInfo().FoundationLevel.toString()}
							class="group-pressed\:scale-110 group-hover\:scale-110 group-focus\:scale-110"
						/>
					</div>
					<NavHelp
						class="absolute -top-4 -right-4"
						actionName="sys-menu"
					/>
				</Activatable>
			</Show>
		</div>
	);
};

export const CreateGameStageHeader = ComponentRegistry.register({
	name: "CreateGameStageHeader",
	createInstance: CreateGameStageHeaderComponent,
	styles: [style],
});
